package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="tareas_reserva") public class TareaReserva{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="tar_id")private Long tarId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="res_id",nullable=false)private Long resId;@Column(name="rag_id")private Long ragId;@Column(name="tar_ord",nullable=false)private Integer tarOrd;@Column(name="tar_tit",nullable=false,length=200)private String tarTit;@Column(name="tar_dur_min",nullable=false)private Integer tarDurMin;@Column(name="tar_est",nullable=false,length=20)private String tarEst;@Column(name="tar_usu_mov",nullable=false,length=100)private String tarUsuMov;@Column(name="tar_fec_mov",nullable=false)private LocalDateTime tarFecMov;@Column(name="tar_act",nullable=false)private Boolean tarAct;
 public Long getTarId(){return tarId;}public void setTarId(Long v){tarId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getResId(){return resId;}public void setResId(Long v){resId=v;}public Long getRagId(){return ragId;}public void setRagId(Long v){ragId=v;}public Integer getTarOrd(){return tarOrd;}public void setTarOrd(Integer v){tarOrd=v;}public String getTarTit(){return tarTit;}public void setTarTit(String v){tarTit=v;}public Integer getTarDurMin(){return tarDurMin;}public void setTarDurMin(Integer v){tarDurMin=v;}public String getTarEst(){return tarEst;}public void setTarEst(String v){tarEst=v;}public String getTarUsuMov(){return tarUsuMov;}public void setTarUsuMov(String v){tarUsuMov=v;}public LocalDateTime getTarFecMov(){return tarFecMov;}public void setTarFecMov(LocalDateTime v){tarFecMov=v;}public Boolean getTarAct(){return tarAct;}public void setTarAct(Boolean v){tarAct=v;}
}
